import { readFileSync, writeFileSync } from 'node:fs';
const lines = readFileSync(new URL('./data/access.log', import.meta.url), 'utf8').split('\n').filter(Boolean);
const byStatus = {};
const paths = {};
let bytes = 0;
for (const l of lines) {
  const m = l.match(/"(\S+) (\S+) [^"]*" (\d{3}) (\S+)$/);
  const path = m[2].split('?')[0];
  byStatus[m[3]] = (byStatus[m[3]] ?? 0) + 1;
  paths[path] = (paths[path] ?? 0) + 1;
  bytes += m[4] === '-' ? 0 : Number(m[4]);
}
const topPaths = Object.entries(paths).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, 3);
writeFileSync(new URL('./summary.json', import.meta.url), JSON.stringify({ requests: lines.length, byStatus, topPaths, bytes }, null, 2) + '\n');
